import{_ as a,o as e,c as n,ag as o}from"./chunks/framework.CxkNbRKf.js";const i="/nada-documentation/images/indicators-frontend-series-description.png",r="/nada-documentation/images/indicators-frontend-chart-data.png",s="/nada-documentation/images/indicators-frontend-api.png",d="/nada-documentation/images/indicators-frontend-structure.png",l="/nada-documentation/images/indicators-frontend-downloads.png",_=JSON.parse('{"title":"Indicators — Catalog frontend","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/content/indicators-frontend.md","filePath":"admin-guide/content/indicators-frontend.md","lastUpdated":1786379412000}'),c={name:"admin-guide/content/indicators-frontend.md"};function h(p,t,g,u,m,f){return e(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="indicators-—-catalog-frontend" tabindex="-1">Indicators — Catalog frontend <a class="header-anchor" href="#indicators-—-catalog-frontend" aria-label="Permalink to &quot;Indicators — Catalog frontend&quot;">​</a></h1><p>Also see <a href="./indicators.html">Publishing indicators</a> and <a href="./indicators-admin.html">Admin UI</a>.</p><p>When an indicator project is published, users can explore it through a dedicated study detail page in the catalog. The page is organized into five tabs.</p><hr><h2 id="series-description" tabindex="-1">Series description <a class="header-anchor" href="#series-description" aria-label="Permalink to &quot;Series description&quot;">​</a></h2><p>The <strong>Series Description</strong> tab is the default view. It displays the full indicator metadata organized into sub-sections accessible from the left navigation panel:</p><ul><li><strong>Overview</strong> — Series unique ID, series name, linked dataset, periodicity, definition, and other key fields.</li><li><strong>Geographic information</strong> — Countries and regions covered.</li><li><strong>API documentation</strong> — Instructions for accessing the data via the API.</li><li><strong>Metadata production</strong> — Provenance of the metadata record.</li></ul><p>The page header shows the indicator title, the list of countries and years covered, the Reference ID, the parent dataset, and a link to download the metadata as JSON.</p><p><img src="'+i+'" alt=""></p><hr><h2 id="chart-data" tabindex="-1">Chart &amp; data <a class="header-anchor" href="#chart-data" aria-label="Permalink to &quot;Chart &amp; data&quot;">​</a></h2><p>The <strong>Chart &amp; Data</strong> tab lets users explore the indicator data interactively.</p><p>On the left, a filter panel exposes all dimension columns defined in the DSD — for example, <strong>Country/area code</strong> (a searchable checklist) and <strong>Time period</strong> (a range slider). Click <strong>Apply</strong> to refresh the chart and data table with the selected filters.</p><p>On the right, the chart displays the filtered data as a line or column chart (toggle with the <strong>Line / Columns</strong> buttons). The chart title, subtitle, and source attribution are shown automatically.</p><p>Below the chart, the <strong>Chart data</strong> table shows the raw values for the current selection, with columns for TIME_PERIOD, VALUE, and the dimension codes. Pagination controls allow browsing all matching rows.</p><p><img src="'+r+'" alt=""></p><hr><h2 id="data-api" tabindex="-1">Data API <a class="header-anchor" href="#data-api" aria-label="Permalink to &quot;Data API&quot;">​</a></h2><p>The <strong>Data API</strong> tab provides documentation and an interactive data explorer for programmatic access to the indicator data.</p><p>The tab includes:</p><ul><li>A description of the indicator series.</li><li><strong>API usage</strong> — Expandable section with example API calls and parameter documentation.</li><li><strong>Bulk data downloads</strong> — Links to download the full dataset.</li><li><strong>Data explorer</strong> — An inline table showing all data rows (DATASET, INDICATOR, INDICATOR_NAME, COUNTRY_CODE, FREQ, TIME_PERIOD, OBS_VALUE), with pagination.</li></ul><p><img src="'+s+'" alt=""></p><hr><h2 id="data-structure" tabindex="-1">Data structure <a class="header-anchor" href="#data-structure" aria-label="Permalink to &quot;Data structure&quot;">​</a></h2><p>The <strong>Data Structure</strong> tab documents the structure of the dataset so users understand the columns and their meaning before working with the data programmatically.</p><p>The table lists all columns in the DSD with:</p><ul><li><strong>Name</strong> — the column identifier used in the CSV and API.</li><li><strong>Label</strong> — a human-readable description of the column.</li><li><strong>Role</strong> — the semantic role of the column, displayed as a colour-coded badge (e.g. ATTRIBUTE, INDICATOR_ID, GEOGRAPHY, PERIODICITY, TIME_PERIOD, OBSERVATION_VALUE).</li><li><strong>Type</strong> — the data type (string, double, integer, etc.).</li><li><strong>Codelist</strong> — the linked codelist ID, if applicable. Click the expand arrow to view the codelist codes inline.</li></ul><p>Use the <strong>Download JSON</strong> or <strong>Download SDMX/XML</strong> buttons to download the full DSD definition.</p><p><img src="'+d+'" alt=""></p><hr><h2 id="downloads" tabindex="-1">Downloads <a class="header-anchor" href="#downloads" aria-label="Permalink to &quot;Downloads&quot;">​</a></h2><p>The <strong>Downloads</strong> tab lists any related resources (files or links) attached to the indicator entry by the catalog administrator, such as documentation, methodology notes, or supplementary data files.</p><p><img src="'+l+'" alt=""></p><p>If no resources have been attached, this tab will appear empty.</p>',34)])])}const I=a(c,[["render",h]]);export{_ as __pageData,I as default};
